void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Center coordinates
    vec2 uv = fragCoord - iResolution.xy / 2.0;

    float br = min(iResolution.x, iResolution.y) * 0.5 * 0.75;    

    vec3 c = vec3(0.0);

    float maxRad = 19.0;

    float speed = 3.5;

    int nDots = 32;

    float freq = 2.0;

    float slice = 3.141592 * 2.0 / float(nDots);

    for (int i = 0; i < nDots; ++i) {

        float is = float(i) * slice;

        float r = maxRad * ((cos(is * freq + iTime * speed) + 1.0) * 0.5);

        vec2 pos = vec2(cos(is), sin(is)) * br;

        c += vec3(step(-r, -length(pos - uv)));
    }

    // Output to screen
    fragColor = vec4(c, 1.0);
}
